"""Writes the whiteboard version of EP01 into scenes.json (replaces older outputs)."""
import json
from pathlib import Path

W = lambda text, x, y, size=72, **k: {"type": "write", "text": text, "x": x, "y": y, "size": size, **k}
M = lambda text, x, y, size=100, **k: W(text, x, y, size, font="marker", **k)
I = lambda name, x, y, size=240, **k: {"type": "icon", "name": name, "x": x, "y": y, "size": size, **k}
C = lambda value, x, y, size=180, **k: {"type": "count", "value": value, "x": x, "y": y, "size": size, **k}
A = lambda f, t, **k: {"type": "arrow", "from": f, "to": t, **k}
BOX = lambda x, y, w, h, **k: {"type": "box", "x": x, "y": y, "w": w, "h": h, **k}
UL = lambda x, y, w, **k: {"type": "underline", "x": x, "y": y, "w": w, **k}
BARS = lambda x, y, w, h, data, **k: {"type": "bars", "x": x, "y": y, "w": w, "h": h, "data": data, **k}


def flywheel():
    nodes = [("low prices", 960, 230, "step one"), ("more members", 1500, 540, "step two"),
             ("more buying power", 960, 850, "step three"), ("even lower prices", 420, 540, "step four")]
    els = []
    for text, x, y, cue in nodes:
        els += [W(text, x, y, 70, at=cue, w=560), BOX(x - 270, y - 62, 540, 124, color="blue", dur=0.5)]
    els += [A([1230, 290], [1430, 470], dur=0.4), A([1430, 620], [1230, 800], dur=0.4),
            A([690, 800], [490, 620], dur=0.4), A([490, 470], [690, 290], dur=0.4),
            M("MEMBERSHIP\nFEES", 960, 540, 64, color="green", at="fee income")]
    return els


